// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/black-han-sans";

export const inter = { variable: "" };
export const blackHanSans = { variable: "" };

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef, useState } from "react";
import "./styles.css";
import { inter, blackHanSans } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

const TITLE = "BLOCK";
const POEMS = [
  { ko: "시는 콘크리트다.", en: "Poetry is concrete.", no: "01" },
  { ko: "단어가 벽이 되고,", en: "Words become walls,", no: "02" },
  { ko: "벽이 시가 된다.", en: "walls become poems.", no: "03" },
  { ko: "무너뜨리지 마라.", en: "Do not demolish.", no: "04" },
];

type Mode = "ko" | "en";

/**
 * BLOCK — 블록, 콘크리트 시 출판. Neo-brutalist poetry press. Stark concrete
 * grids, heavy type, zero easing. The signature: clip-path-reveal (sections
 * wipe in with hard geometric cuts), marquee (scrolling manifesto ticker),
 * flip-layout (KO/EN mode toggle FLIP-rearranges the poems). Distinct from
 * BLUNT (riso/paper/yellow) and RAVE (dark/strobe/blue) — BLOCK is grey
 * concrete, green ink, structural.
 */
export default function BlockPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();
  const [mode, setMode] = useState<Mode>("ko");

  useEffect(() => {
    rootRef.current?.classList.add("block-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "block" }, "*");
  }, []);

  return (
    <div
      ref={rootRef}
      className={`${inter.variable} ${blackHanSans.variable} block-root`}
      data-mode={mode}
    >
      <div ref={revealRef} className="block-doc">
        <header className="block-hero" data-reveal="">
          <p className="block-kicker">
            <span lang="ko">콘크리트 시 출판</span> · CONCRETE POETRY PRESS
          </p>
          <h1 className="block-title" aria-label="BLOCK 블록">
            {TITLE}
            <span lang="ko" className="block-title__ko">블록</span>
          </h1>
          <p className="block-sub">
            <span lang="ko">단단한 그리드. 무거운 활자. 타협 없음.</span>
          </p>
        </header>

        {/* marquee — scrolling manifesto ticker */}
        <div className="block-marquee" aria-hidden="true">
          <span className="block-marquee__track">
            ◆ <span lang="ko">시는 콘크리트</span> POETRY IS CONCRETE ◆{" "}
            <span lang="ko">단어가 벽</span> WORDS ARE WALLS ◆{" "}
            <span lang="ko">벽이 시</span> WALLS ARE POEMS ◆{" "}
            <span lang="ko">무너뜨리지 마라</span> DO NOT DEMOLISH ◆
          </span>
        </div>

        {/* flip-layout — KO/EN mode toggle rearranges poems */}
        <section className="block-poems" aria-labelledby="block-poems-title">
          <div className="block-poems__head" data-reveal="">
            <h2 id="block-poems-title" className="block-secthead">
              <span lang="ko">작품</span> · WORKS
            </h2>
            <div className="block-mode-toggle">
              <button
                type="button"
                className={`block-mode-btn ${mode === "ko" ? "is-active" : ""}`}
                onClick={() => setMode("ko")}
              >
                <span lang="ko">한글</span>
              </button>
              <button
                type="button"
                className={`block-mode-btn ${mode === "en" ? "is-active" : ""}`}
                onClick={() => setMode("en")}
              >
                EN
              </button>
            </div>
          </div>

          <ol className="block-poem-list">
            {POEMS.map((p) => (
              <li key={p.no} className="block-poem" data-reveal="">
                <span className="block-poem__no">{p.no}</span>
                <div className="block-poem__body">
                  <p className="block-poem__ko" lang="ko">
                    {p.ko}
                  </p>
                  <p className="block-poem__en">
                    {p.en}
                  </p>
                </div>
              </li>
            ))}
          </ol>
        </section>

        {/* clip-path-reveal — manifesto wipes in with hard cuts */}
        <section className="block-manifesto" data-reveal="">
          <p className="block-manifesto__text">
            <span lang="ko">
              우리는 부드러움을 거부한다. 시는 벽이다. 벽은 서 있어야 한다.
            </span>
          </p>
          <p className="block-manifesto__text block-manifesto__text--en">
            We reject softness. Poetry is a wall. A wall must stand.
          </p>
        </section>

        <footer className="block-foot" data-reveal="">
          <p>© 2026 BLOCK · <span lang="ko">블록</span> · MIT</p>
          <p>
            <span lang="ko">이징 없음 — 코드로 지었다.</span> no easing — built
            in code.
          </p>
        </footer>
      </div>
    </div>
  );
}

/* BLOCK 블록 — concrete poetry press · neo-brutalist
   concrete grey / green ink / hard shadows / zero easing */

.block-root {
  --block-bg: #e5e5e5;
  --block-concrete: #d4d4d4;
  --block-ink: #171717;
  --block-ink-soft: #404040;
  --block-green: #22c55e;
  --block-green-deep: #16a34a;
  --block-rule: #404040;

  position: relative;
  min-height: 100vh;
  background: var(--block-bg);
  color: var(--block-ink);
  font-family: "Inter", "Black Han Sans", sans-serif;
  font-weight: 500;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.6;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Raw concrete grain — an SVG fractal-noise data URI laid over the slab.
   Static; brutalism has no ambient motion. */
.block-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.5;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.09  0 0 0 0 0.09  0 0 0 0 0.09  0 0 0 0.06 0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  mix-blend-mode: multiply;
}
.block-doc { position: relative; z-index: 1; }

.block-root :lang(ko) { font-family: "Black Han Sans", sans-serif; }
.block-root ::selection { background: var(--block-green); color: #fff; }
.block-root :focus-visible { outline: 3px solid var(--block-ink); outline-offset: 4px; }

/* Reveal — brutalist: clip-path hard cuts, no soft fades */
.block-js [data-reveal] {
  clip-path: inset(0 100% 0 0);
  transition: clip-path 500ms steps(8);
}
.block-js [data-reveal].is-visible { clip-path: inset(0 0% 0 0); }
@media (prefers-reduced-motion: reduce) {
  .block-js [data-reveal] { clip-path: none; transition: none; }
}

/* Hero */
.block-hero {
  padding: clamp(80px, 16vh, 140px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 60px);
  border-bottom: 4px solid var(--block-ink);
}
.block-kicker {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--block-green-deep);
  margin: 0 0 30px;
  display: inline-block;
  background: var(--block-ink);
  color: var(--block-green);
  padding: 6px 14px;
}
.block-title {
  font-weight: 900;
  font-size: clamp(4rem, 16vw, 12rem);
  line-height: 0.85;
  letter-spacing: -0.04em;
  margin: 0 0 20px;
  text-shadow: 8px 8px 0 var(--block-green);
}
.block-title__ko {
  display: block;
  font-size: 0.28em;
  font-weight: 700;
  letter-spacing: 0.1em;
  margin-top: 16px;
  text-shadow: none;
  color: var(--block-ink-soft);
}
.block-sub {
  font-size: clamp(1rem, 2vw, 1.3rem);
  font-weight: 700;
  margin: 0;
  border-left: 6px solid var(--block-green);
  padding-left: 16px;
}

/* Marquee */
.block-marquee {
  overflow: hidden;
  background: var(--block-ink);
  color: var(--block-green);
  padding: 14px 0;
  white-space: nowrap;
  border-bottom: 4px solid var(--block-green);
}
.block-marquee__track {
  display: inline-block;
  font-weight: 900;
  font-size: 0.9rem;
  letter-spacing: 0.1em;
  animation: block-marquee 28s linear infinite;
  padding-left: 100%;
}
@keyframes block-marquee { to { transform: translateX(-100%); } }
@media (prefers-reduced-motion: reduce) {
  .block-marquee__track { animation: none; padding-left: 0; }
}

/* Poems + flip-layout mode toggle */
.block-poems {
  padding: clamp(60px, 12vh, 100px) clamp(20px, 5vw, 60px);
  max-width: 900px;
  margin: 0 auto;
}
.block-poems__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 48px;
  flex-wrap: wrap;
  gap: 16px;
}
.block-secthead {
  font-size: 1rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin: 0;
}
.block-mode-toggle {
  display: flex;
  gap: 0;
  border: 3px solid var(--block-ink);
}
.block-mode-btn {
  background: transparent;
  border: none;
  padding: 8px 18px;
  font-weight: 900;
  font-size: 0.85rem;
  letter-spacing: 0.1em;
  cursor: pointer;
  font-family: inherit;
  color: var(--block-ink);
  transition: none;
}
.block-mode-btn.is-active {
  background: var(--block-ink);
  color: var(--block-green);
}

/* flip-layout: KO mode shows Korean first, EN mode shows English first */
.block-poem-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: 0;
}
.block-poem {
  display: flex;
  gap: 24px;
  align-items: baseline;
  padding: 28px 0;
  border-top: 2px solid var(--block-rule);
  transition: none;
}
.block-poem:last-child { border-bottom: 2px solid var(--block-rule); }
.block-poem__no {
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 900;
  color: var(--block-green);
  min-width: 2.5ch;
}
.block-poem__body { flex: 1; }
.block-poem__ko {
  font-size: clamp(1.3rem, 3vw, 2rem);
  font-weight: 700;
  margin: 0 0 6px;
  line-height: 1.3;
}
.block-poem__en {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--block-ink-soft);
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
/* In EN mode, English becomes primary (larger) and Korean secondary */
.block-root[data-mode="en"] .block-poem__en {
  font-size: clamp(1.3rem, 3vw, 2rem);
  font-weight: 700;
  color: var(--block-ink);
  text-transform: none;
  letter-spacing: 0;
  margin-bottom: 6px;
}
.block-root[data-mode="en"] .block-poem__ko {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--block-ink-soft);
}

/* Manifesto */
.block-manifesto {
  background: var(--block-ink);
  color: #fff;
  padding: clamp(60px, 12vh, 100px) clamp(20px, 5vw, 60px);
  text-align: center;
}
.block-manifesto__text {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 900;
  margin: 0 0 16px;
  line-height: 1.3;
}
.block-manifesto__text--en {
  font-size: clamp(0.95rem, 1.8vw, 1.2rem);
  font-weight: 500;
  color: var(--block-green);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

/* Footer */
.block-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  border-top: 4px solid var(--block-ink);
  font-size: 0.82rem;
  font-weight: 700;
}
.block-foot p { margin: 0 0 6px; }
